-- Disposable local database only. Every client, consent and token is synthetic.
begin;
select set_config('tr8.oauth_test_checks','0',true);
create temporary table oauth_values(key text primary key,value jsonb) on commit drop;
create function pg_temp.oassert(ok boolean,label text) returns void language plpgsql as $$begin
 if ok is distinct from true then raise exception 'OAuth assertion failed: %',label;end if;
 perform set_config('tr8.oauth_test_checks',(current_setting('tr8.oauth_test_checks')::integer+1)::text,true);
end;$$;
create function pg_temp.oput(k text,v jsonb) returns void language sql as $$insert into pg_temp.oauth_values values(k,v) on conflict(key)do update set value=excluded.value;$$;
create function pg_temp.oget(k text) returns jsonb language sql as $$select value from pg_temp.oauth_values where key=k;$$;
create function pg_temp.oactor(n integer,live boolean default true) returns void language sql as $$
 select set_config('request.jwt.claims',jsonb_build_object('sub','ed000000-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','session_id',case when live then 'ed000000-0000-4000-8000-'||lpad(n::text,12,'0') end)::text,true)::text::void;
$$;
create function pg_temp.oerror(command text,code text,label text) returns void language plpgsql as $$declare r jsonb;begin
 begin execute command into r; if coalesce(r#>>'{_tr8_oauth_error,code}',r#>>'{_tr8_mcp_error,code}')=code then perform pg_temp.oassert(true,label);return;end if;
 exception when others then if sqlstate=code or sqlerrm=code then perform pg_temp.oassert(true,label);return;end if;raise exception 'OAuth assertion failed %: expected %, actual % %',label,code,sqlstate,sqlerrm;end;
 raise exception 'OAuth assertion failed %: expected %, actual %',label,code,r;
end;$$;
create function pg_temp.obegin(p_scopes jsonb default '["finance:read","finance:write"]'::jsonb) returns jsonb language sql as $$
 select public.tr8_mcp_oauth_server('begin',jsonb_build_object('client_id','synthetic-client','redirect_uri','https://client.example/callback','code_challenge','7w_YNF9DSfIdPf_pRjSq646_kPr-2-o9NAl16JGghdM','state','synthetic-state','resource','https://tr8.vercel.app/api/mcp/finance','scopes',p_scopes));
$$;
create function pg_temp.oexchange(code text,patch jsonb default '{}'::jsonb) returns jsonb language sql as $$
 select public.tr8_mcp_oauth_server('exchange',jsonb_build_object('client_id','synthetic-client','code',code,'code_verifier',repeat('v',43),'redirect_uri','https://client.example/callback','resource','https://tr8.vercel.app/api/mcp/finance')||patch);
$$;
do $$begin execute format('grant usage on schema %I to anon,authenticated',pg_my_temp_schema()::regnamespace::text);end;$$;
grant all on pg_temp.oauth_values to anon,authenticated;
grant execute on function pg_temp.oassert(boolean,text),pg_temp.oput(text,jsonb),pg_temp.oget(text),pg_temp.oactor(integer,boolean),pg_temp.oerror(text,text,text),pg_temp.obegin(jsonb),pg_temp.oexchange(text,jsonb) to anon,authenticated;
select pg_temp.oassert((select not enabled from tr8_private.mcp_oauth_config),'migration stays disabled');
select pg_temp.oassert((select count(*)=0 from tr8_private.mcp_oauth_clients),'no real/static clients provisioned');
select pg_temp.oassert(not has_function_privilege('anon','tr8_private.mcp_finance_dispatch_credential(uuid,text,jsonb)','EXECUTE'),'caller-selected credential core not public');
select pg_temp.oassert(not has_function_privilege('authenticated','tr8_private.mcp_finance_dispatch_credential(uuid,text,jsonb)','EXECUTE'),'browser cannot call private credential core');
set local role anon;
select pg_temp.oerror($q$select public.tr8_mcp_oauth_server('get_client','{"client_id":"synthetic-client"}')$q$,'temporarily_unavailable','disabled gate authoritative in SQL');
select pg_temp.oerror($q$select * from tr8_private.mcp_oauth_access$q$,'42501','access hashes not exposed');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_consent('list')$q$,'42501','anonymous consent management denied');
reset role;

update tr8_private.mcp_oauth_config set enabled=true;
insert into tr8_private.mcp_oauth_clients values('synthetic-client','Synthetic ChatGPT',array['https://client.example/callback'],true),('other-client','Other synthetic',array['https://other.example/callback'],true);
insert into auth.users(id,email,email_confirmed_at) select ('ed000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'oauth-'||n||'@example.test',clock_timestamp() from generate_series(1,2)n;
insert into auth.sessions(id,user_id) select id,id from auth.users where id::text like 'ed000000%';
insert into tr8_private.app_users(user_id) select id from auth.users where id::text like 'ed000000%';
insert into tr8_private.workspaces(id,owner_id,kind,name) select ('ed000010-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('ed000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'personal','Synthetic OAuth' from generate_series(1,2)n;
insert into tr8_private.workspace_members(workspace_id,user_id) select id,owner_id from tr8_private.workspaces where id::text like 'ed000010%';
insert into tr8_private.mcp_credentials(id,owner_id,workspace_id,name,access,token_hash,expires_at)
 select ('ed000030-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'ed000000-0000-4000-8000-000000000001','ed000010-0000-4000-8000-000000000001','Synthetic finance '||n,'read',encode(sha256(convert_to('tr8_mcp_'||repeat(chr(96+n),64),'UTF8')),'hex'),clock_timestamp()+interval '45 days' from generate_series(1,2)n;
insert into tr8_private.account_finances values('ed000000-0000-4000-8000-000000000001',1,
'{"schemaVersion":1,"financialSpace":{"domainSchemaVersion":5,"currencyCatalogVersion":"currency-catalog-v1","currencyDefinitions":[{"code":"DOP","minorUnitDigits":2},{"code":"USD","minorUnitDigits":2},{"code":"EUR","minorUnitDigits":2},{"code":"BOB","minorUnitDigits":2}],"accounts":[{"id":"synthetic-dop","type":"debit","name":"Synthetic DOP","currency":"DOP","openingBalanceMinor":1000000,"openingDate":"2026-01-01"}],"operations":[],"plans":[]}}',gen_random_uuid(),clock_timestamp());
insert into tr8_private.mcp_finance_grants(credential_id,owner_id,access,mailbox_ids,expense_categories,income_categories)
 select id,owner_id,case when id::text like '%000001' then 'write' else 'read' end,
 case when id::text like '%000001' then array[repeat('a',64)] else array[]::text[] end,
 case when id::text like '%000001' then array['other'] else array[]::text[] end,
 case when id::text like '%000001' then array['salary','other'] else array[]::text[] end from tr8_private.mcp_credentials where id::text like 'ed000030%';
insert into tr8_private.mcp_finance_accounts select id,'synthetic-dop','2026-01-02T00:00:00Z' from tr8_private.mcp_credentials where id::text like 'ed000030%';
select pg_temp.oput('ledger_before',(select to_jsonb(f) from tr8_private.account_finances f where owner_id='ed000000-0000-4000-8000-000000000001'));
set local role anon;
select pg_temp.oassert(public.tr8_mcp_oauth_server('get_client','{"client_id":"missing"}') is null,'unknown clients cannot auto-register');
select pg_temp.oassert(public.tr8_mcp_oauth_server('get_client','{"client_id":"synthetic-client"}')->>'token_endpoint_auth_method'='none','public PKCE client metadata');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_server('begin','{"client_id":"synthetic-client","redirect_uri":"https://evil.example/callback","code_challenge":"7w_YNF9DSfIdPf_pRjSq646_kPr-2-o9NAl16JGghdM","resource":"https://tr8.vercel.app/api/mcp/finance","scopes":["finance:read"]}')$q$,'invalid_request','unregistered redirect denied');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_server('begin','{"client_id":"synthetic-client","redirect_uri":"https://client.example/callback","code_challenge":"7w_YNF9DSfIdPf_pRjSq646_kPr-2-o9NAl16JGghdM","resource":"https://evil.example","scopes":["finance:read"]}')$q$,'invalid_request','resource binding enforced');
select pg_temp.oerror($q$select pg_temp.obegin('["projects:write"]')$q$,'invalid_scope','project scopes not supported');
select pg_temp.oput('attempt',pg_temp.obegin());
select pg_temp.oassert(pg_temp.oget('attempt')->>'attempt' ~ '^tr8_oauth_p_[a-f0-9]{64}$','unguessable pending attempt');
reset role;
set local role authenticated;
select pg_temp.oactor(1,false);
select pg_temp.oerror($q$select public.tr8_mcp_oauth_consent('details',jsonb_build_object('attempt',pg_temp.oget('attempt')->>'attempt'))$q$,'42501','consent requires real live session');
select pg_temp.oactor(1);
select pg_temp.oput('details',public.tr8_mcp_oauth_consent('details',jsonb_build_object('attempt',pg_temp.oget('attempt')->>'attempt')));
select pg_temp.oassert(pg_temp.oget('details')->>'client_name'='Synthetic ChatGPT','consent identifies actual static client');
select pg_temp.oassert(jsonb_array_length(pg_temp.oget('details')->'connections')=1,'write request only exposes already-write-authorized finance grants');
select pg_temp.oassert(pg_temp.oget('details')#>>'{connections,0,accounts,0,name}'='Synthetic DOP','consent displays actual account identity');
select pg_temp.oactor(2);
select pg_temp.oerror($q$select public.tr8_mcp_oauth_consent('details',jsonb_build_object('attempt',pg_temp.oget('attempt')->>'attempt'))$q$,'42501','attempt bound to original browser owner');
select pg_temp.oactor(1);
select pg_temp.oerror($q$select public.tr8_mcp_oauth_consent('approve',jsonb_build_object('attempt',pg_temp.oget('attempt')->>'attempt','credential_id','ed000030-0000-4000-8000-000000000002','grant_fingerprint',(select x->>'grant_fingerprint' from jsonb_array_elements(pg_temp.oget('read_details')->'connections')x where x->>'credential_id'='ed000030-0000-4000-8000-000000000002')))$q$,'invalid_scope','read parent cannot approve write');
select pg_temp.oput('approval',public.tr8_mcp_oauth_consent('approve',jsonb_build_object('attempt',pg_temp.oget('attempt')->>'attempt','credential_id','ed000030-0000-4000-8000-000000000001','grant_fingerprint',pg_temp.oget('details')#>>'{connections,0,grant_fingerprint}')));
select pg_temp.oassert(pg_temp.oget('approval')->>'redirect_uri'='https://client.example/callback' and pg_temp.oget('approval')->>'state'='synthetic-state','bound callback/state returned');
select pg_temp.oassert(pg_temp.oget('approval')->>'code' ~ '^tr8_oauth_c_[a-f0-9]{64}$','opaque authorization code');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_consent('approve',jsonb_build_object('attempt',pg_temp.oget('attempt')->>'attempt','credential_id','ed000030-0000-4000-8000-000000000001','grant_fingerprint',pg_temp.oget('details')#>>'{connections,0,grant_fingerprint}'))$q$,'invalid_request','consent attempt cannot approve twice');
reset role;
set local role anon;
select pg_temp.oerror($q$select pg_temp.oexchange(pg_temp.oget('approval')->>'code','{"client_id":"other-client"}')$q$,'invalid_grant','authorization code bound to client');
select pg_temp.oerror($q$select pg_temp.oexchange(pg_temp.oget('approval')->>'code','{"code_verifier":"xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"}')$q$,'invalid_grant','wrong PKCE denied without consuming valid code');
select pg_temp.oput('tokens',pg_temp.oexchange(pg_temp.oget('approval')->>'code'));
select pg_temp.oassert(pg_temp.oget('tokens')->>'access_token' ~ '^tr8_oauth_a_[a-f0-9]{64}$','independent access token is not Supabase JWT or MCP PAT');
select pg_temp.oassert(pg_temp.oget('tokens')->>'refresh_token' ~ '^tr8_oauth_r_[a-f0-9]{64}$','refresh token has separate prefix');
select pg_temp.oassert((pg_temp.oget('tokens')->>'expires_in')::integer between 1 and 900,'access at most fifteen minutes');
select pg_temp.oerror($q$select pg_temp.oexchange(pg_temp.oget('approval')->>'code')$q$,'invalid_grant','authorization code single-use');
select pg_temp.oput('verified',public.tr8_mcp_oauth_server('verify',jsonb_build_object('token',pg_temp.oget('tokens')->>'access_token','resource','https://tr8.vercel.app/api/mcp/finance')));
select pg_temp.oassert(pg_temp.oget('verified')->>'client_id'='synthetic-client','verification bound to client');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_server('verify',jsonb_build_object('token',pg_temp.oget('tokens')->>'access_token','resource','https://evil.example'))$q$,'invalid_token','wrong audience/resource denied');
select pg_temp.oassert(public.tr8_mcp_oauth_finance_dispatch(pg_temp.oget('tokens')->>'access_token','finance_list_accounts')->'items'->0->>'id'='synthetic-dop','OAuth token can only consult approved finance account');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_finance_dispatch(pg_temp.oget('tokens')->>'access_token','list_projects')$q$,'PT403','OAuth bridge rejects project tool actions');
select pg_temp.oerror($q$select public.tr8_mcp_finance_dispatch(pg_temp.oget('tokens')->>'access_token','finance_context')$q$,'PT401','legacy PAT endpoint rejects opaque OAuth prefix');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_server('refresh',jsonb_build_object('client_id','synthetic-client','refresh_token',pg_temp.oget('tokens')->>'refresh_token','resource','https://tr8.vercel.app/api/mcp/finance','scopes',jsonb_build_array('finance:read','finance:write','projects:read')))$q$,'invalid_scope','refresh cannot add unrelated permissions');
select pg_temp.oput('rotated',public.tr8_mcp_oauth_server('refresh',jsonb_build_object('client_id','synthetic-client','refresh_token',pg_temp.oget('tokens')->>'refresh_token','resource','https://tr8.vercel.app/api/mcp/finance','scopes',jsonb_build_array('finance:read'))));
select pg_temp.oassert(pg_temp.oget('rotated')->>'scope'='finance:read','refresh may narrow scope');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_finance_dispatch(pg_temp.oget('rotated')->>'access_token','finance_submit_notice','{}')$q$,'PT403','read access cannot write even with write parent');
select pg_temp.oassert(public.tr8_mcp_oauth_finance_dispatch(pg_temp.oget('rotated')->>'access_token','finance_context')->>'access'='read','context reports effective OAuth scope');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_server('refresh',jsonb_build_object('client_id','other-client','refresh_token',pg_temp.oget('tokens')->>'refresh_token','resource','https://tr8.vercel.app/api/mcp/finance'))$q$,'invalid_grant','wrong client cannot revoke family by replay');
select pg_temp.oassert(not public.tr8_mcp_oauth_server('verify',jsonb_build_object('token',pg_temp.oget('rotated')->>'access_token','resource','https://tr8.vercel.app/api/mcp/finance'))?'_tr8_oauth_error','other client replay leaves family active');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_server('refresh',jsonb_build_object('client_id','synthetic-client','refresh_token',pg_temp.oget('tokens')->>'refresh_token','resource','https://tr8.vercel.app/api/mcp/finance'))$q$,'invalid_grant','used refresh reuse rejected');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_server('verify',jsonb_build_object('token',pg_temp.oget('rotated')->>'access_token','resource','https://tr8.vercel.app/api/mcp/finance'))$q$,'invalid_token','reuse revokes entire token family persistently');
reset role;
select pg_temp.oassert((select bool_and(revoked_at is not null) from tr8_private.mcp_oauth_grants),'replay revocation committed despite error envelope');
set local role anon;
select pg_temp.oput('read_attempt',pg_temp.obegin('["finance:read"]'));
reset role;
set local role authenticated;
select pg_temp.oactor(1);
select pg_temp.oput('read_details',public.tr8_mcp_oauth_consent('details',jsonb_build_object('attempt',pg_temp.oget('read_attempt')->>'attempt')));
select pg_temp.oassert(jsonb_array_length(pg_temp.oget('read_details')->'connections')=2,'read consent may choose either current finance grant');
select pg_temp.oassert((select x->'mailbox_ids'='[]'::jsonb and x->'expense_categories'='[]'::jsonb and x->'income_categories'='[]'::jsonb from jsonb_array_elements(pg_temp.oget('read_details')->'connections')x where x->>'credential_id'='ed000030-0000-4000-8000-000000000002'),'read consent accepts real grant without mailbox or import categories');
select pg_temp.oput('read_approval',public.tr8_mcp_oauth_consent('approve',jsonb_build_object('attempt',pg_temp.oget('read_attempt')->>'attempt','credential_id','ed000030-0000-4000-8000-000000000002','grant_fingerprint',(select x->>'grant_fingerprint' from jsonb_array_elements(pg_temp.oget('read_details')->'connections')x where x->>'credential_id'='ed000030-0000-4000-8000-000000000002'))));
select pg_temp.oassert(jsonb_array_length(public.tr8_mcp_oauth_consent('list')->'items')=2,'owner can list active and revoked grants');
select pg_temp.oactor(2);
select pg_temp.oassert(jsonb_array_length(public.tr8_mcp_oauth_consent('list')->'items')=0,'grant listing isolated by owner');
select pg_temp.oactor(1);
reset role;
set local role anon;
select pg_temp.oput('read_tokens',pg_temp.oexchange(pg_temp.oget('read_approval')->>'code'));
select pg_temp.oput('read_info',public.tr8_mcp_oauth_server('verify',jsonb_build_object('token',pg_temp.oget('read_tokens')->>'access_token','resource','https://tr8.vercel.app/api/mcp/finance')));
select pg_temp.oassert(pg_temp.oget('read_info')->>'grant_id' is not null,'fresh read-only grant works');
select pg_temp.oassert(jsonb_array_length(public.tr8_mcp_oauth_finance_dispatch(pg_temp.oget('read_tokens')->>'access_token','finance_list_accounts')->'items')=1,'OAuth read-only account consultation needs no mailbox');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_finance_dispatch(pg_temp.oget('read_tokens')->>'access_token','finance_submit_notice','{}')$q$,'PT403','mailbox-free read OAuth cannot submit movements');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_server('refresh',jsonb_build_object('client_id','synthetic-client','refresh_token',pg_temp.oget('read_tokens')->>'refresh_token','resource','https://tr8.vercel.app/api/mcp/finance','scopes',jsonb_build_array('finance:read','finance:write')))$q$,'invalid_scope','read refresh cannot escalate to finance write');
reset role;
select pg_temp.oassert((select expires_at<=created_at+interval '30 days' from tr8_private.mcp_oauth_grants where id=(pg_temp.oget('read_info')->>'grant_id')::uuid),'absolute grant lifetime thirty days');
update tr8_private.mcp_finance_grants set updated_at=updated_at+interval '1 microsecond' where credential_id='ed000030-0000-4000-8000-000000000002';
set local role anon;
select pg_temp.oerror($q$select public.tr8_mcp_oauth_server('verify',jsonb_build_object('token',pg_temp.oget('read_tokens')->>'access_token','resource','https://tr8.vercel.app/api/mcp/finance'))$q$,'invalid_token','any parent grant revision requires new consent');
select pg_temp.oassert(public.tr8_mcp_oauth_server('revoke',jsonb_build_object('client_id','other-client','token',pg_temp.oget('read_tokens')->>'refresh_token'))='{}'::jsonb,'wrong client revocation reveals no token existence');
reset role;
select pg_temp.oassert((select revoked_at is null from tr8_private.mcp_oauth_grants where id=(pg_temp.oget('read_info')->>'grant_id')::uuid),'wrong client cannot revoke another token family');
set local role authenticated;
select pg_temp.oactor(2);
select pg_temp.oerror($q$select public.tr8_mcp_oauth_consent('revoke',jsonb_build_object('grant_id',pg_temp.oget('read_info')->>'grant_id'))$q$,'PT404','other user cannot revoke a grant');
select pg_temp.oactor(1);
select pg_temp.oassert(public.tr8_mcp_oauth_consent('revoke',jsonb_build_object('grant_id',pg_temp.oget('read_info')->>'grant_id'))->>'revoked'='true','owner can revoke even after parent revision');
reset role;
set local role anon;
select pg_temp.oput('denied_attempt',pg_temp.obegin('["finance:read"]'));
reset role;
set local role authenticated;
select pg_temp.oactor(1);
select public.tr8_mcp_oauth_consent('details',jsonb_build_object('attempt',pg_temp.oget('denied_attempt')->>'attempt'));
select pg_temp.oassert(public.tr8_mcp_oauth_consent('deny',jsonb_build_object('attempt',pg_temp.oget('denied_attempt')->>'attempt'))->>'error'='access_denied','denial yields bound OAuth error');
reset role;
select pg_temp.oassert((select count(*)=2 from tr8_private.mcp_oauth_grants),'denial creates no grant');
set local role anon;
select pg_temp.oput('stale_attempt',pg_temp.obegin('["finance:read"]'));
reset role;
set local role authenticated;
select pg_temp.oactor(1);
select pg_temp.oput('stale_details',public.tr8_mcp_oauth_consent('details',jsonb_build_object('attempt',pg_temp.oget('stale_attempt')->>'attempt')));
select pg_temp.oassert(pg_temp.oget('stale_details')#>>'{connections,0,grant_fingerprint}' ~ '^[a-f0-9]{64}$','details binds exact reviewed scope revision');
select pg_temp.oerror($q$select public.tr8_mcp_oauth_consent('approve',jsonb_build_object('attempt',pg_temp.oget('stale_attempt')->>'attempt','credential_id','ed000030-0000-4000-8000-000000000001'))$q$,'22023','direct approval must supply reviewed fingerprint');
reset role;
update tr8_private.mcp_finance_grants set updated_at=updated_at+interval '1 microsecond' where credential_id='ed000030-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.oactor(1);
select pg_temp.oerror($q$select public.tr8_mcp_oauth_consent('approve',jsonb_build_object('attempt',pg_temp.oget('stale_attempt')->>'attempt','credential_id','ed000030-0000-4000-8000-000000000001','grant_fingerprint',pg_temp.oget('stale_details')#>>'{connections,0,grant_fingerprint}'))$q$,'PT409','changed parent permission cannot be approved from stale consent');
reset role;
select pg_temp.oassert((select count(*)=2 from tr8_private.mcp_oauth_grants),'stale consent does not create an OAuth grant');
-- A removed account must not poison another eligible connection's consent DTO.
update tr8_private.mcp_finance_accounts set account_id='removed-account' where credential_id='ed000030-0000-4000-8000-000000000002';
set local role authenticated;
select pg_temp.oactor(1);
select pg_temp.oput('filtered_details',public.tr8_mcp_oauth_consent('details',jsonb_build_object('attempt',pg_temp.oget('stale_attempt')->>'attempt')));
select pg_temp.oassert(jsonb_array_length(pg_temp.oget('filtered_details')->'connections')=1,'removed-account grant omitted while valid grant remains selectable');
reset role;
select pg_temp.oassert((select bool_and(attempt_hash !~ '^tr8_oauth_' and length(attempt_hash)=64) from tr8_private.mcp_oauth_attempts),'only pending attempt hashes stored');
select pg_temp.oassert((select bool_and(code_hash !~ '^tr8_oauth_' and length(code_hash)=64) from tr8_private.mcp_oauth_codes),'only authorization code hashes stored');
select pg_temp.oassert((select bool_and(token_hash !~ '^tr8_oauth_' and length(token_hash)=64) from tr8_private.mcp_oauth_access),'only access token hashes stored');
select pg_temp.oassert((select bool_and(token_hash !~ '^tr8_oauth_' and length(token_hash)=64) from tr8_private.mcp_oauth_refresh),'only refresh token hashes stored');
select pg_temp.oassert((select to_jsonb(f)=pg_temp.oget('ledger_before') from tr8_private.account_finances f where owner_id='ed000000-0000-4000-8000-000000000001'),'OAuth flow never alters the financial ledger');
select current_setting('tr8.oauth_test_checks')::integer checks;
rollback;
